    "explanation_default": "Ta konfiguracja generuje składnię niezbędną dla wybranej platformy. Większość polityk firewall jest wykonywana w kolejności od góry do dołu.",
    "generate": "Generuj konfigurację ACL",
    "platform_cisco_ios": "Cisco IOS (Extended ACL)",
    "platform_junos": "Juniper JunOS (Filter)",
    "platform_iptables": "Linux iptables",
    "platform_nftables": "Linux nftables",
    "platform_pfsense": "pfSense / opnSense",
    "platform_aws_sg": "AWS Security Group / NACL",
    "platform_windows": "Zapora Windows (PowerShell)",
    "platform_cisco_asa": "Cisco ASA",
    "platform_palo_alto": "Palo Alto (PAN-OS)",
