    "type_prefix": "Typ ",
    "polarity_desc_A": "Kabel prosty (straight-through). Key-up na Końcu A, key-down na Końcu B. Obrócenie złącza na Końcu B odwraca rząd włókien — pozycja n na Końcu A trafia na pozycję (suma+1−n) na Końcu B.",
    "polarity_desc_B": "Kabel odwrócony (key-up do key-up). Pozycja włókna n na Końcu A mapuje się bezpośrednio na pozycję n na Końcu B. Wykonany z jednym złączem obróconym wewnętrznie, aby znieść odwrócenie rzędu.",
    "polarity_desc_C": "Kabel z zamienionymi parami sąsiednimi. Key-up na Końcu A, key-down na Końcu B. Kolejne pary włókien są zamieniane miejscami przed obróceniem złącza końcowego — stosowany tam, gdzie moduły kasetowe wymagają wyrównania par.",
