    "note_pins_label": "Męski vs Żeński",
    "note_pins": "Złącza męskie mają piny prowadzące; złącza żeńskie mają otwory prowadzące. Transceivery używają żeńskiego MPO; kable krosowe to zazwyczaj męski-żeński.",
