    "t568a_desc": "T568A — Preferowany w instalacjach domowych i przebiegach poziomych (TIA-568). Para zielona na pinach 1–2. Pary 2 i 3 są w odwrotnej kolejności w porównaniu do T568B.",
    "t568b_desc": "T568B — Dominujący w komercyjnych wdrożeniach w Ameryce Północnej. Para pomarańczowa na pinach 1–2. Elektrycznie identyczny z T568A, z zamienionymi parami 2 i 3.",
    "crossover_desc": "Kabel krosowany (cross): T568A na Końcu A, T568B na Końcu B. Zamienia pary 2 i 3, umożliwiając bezpośrednie połączenia między urządzeniami (PC-PC, switch-switch) bez przełącznika pośredniego.",
