    "sysctl_apply_hint": "Zastosuj za pomocą: sysctl -p /etc/sysctl.d/99-tcp-tuning.conf. Wartości są obliczane na podstawie Twojego BDP.",
    "ref_title": "Referencja Algorytmu",
    "ref_reno_desc": "Klasyczny algorytm AIMD. Slow start podwaja cwnd co każde RTT aż do ssthresh. Congestion avoidance dodaje ~1 segment na każde RTT. Przy 3 duplikowanych ACK: ssthresh = cwnd/2, cwnd = ssthresh. Przy timeout: cwnd = 1 MSS. Sprawiedliwy, ale słabo wykorzystuje ścieżki o wysokim BDP po utracie.",
    "ref_cubic_desc": "Domyślny w Linux. Używa funkcji sześciennej W(t) = C(t-K)^3 + W_max (C=0,4, beta=0,7). Po utracie cwnd spada do 70% W_max, następnie rośnie przez krzywą wklęsło-wypukłą. Bardziej agresywny niż Reno w long-fat networks. K = (W_max * 0,3 / C)^(1/3).",
    "ref_bbr_desc": "Algorytm Google oparty na modelu. Szacuje przepustowość wąskiego gardła i minimalny RTT zamiast używać utraty jako sygnału. Fazy: Startup (zysk 2,89x), Drain, ProbeBW (8-fazowy cykl zysku: 1,25/0,75/1...), ProbeRTT (4 segmenty co około 10s). Osiąga pełną przepustowość nawet przy stratach.",
    "phase_startup": "Startup",
    "phase_drain": "Drain",
    "phase_probe_bw": "ProbeBW",
    "phase_probe_rtt": "ProbeRTT",
