    "ipvlan_note": "IPvLAN współdzieli adres MAC interfejsu nadrzędnego. Tryb L2 korzysta z tej samej domeny rozgłoszeniowej; tryb L3 rutuje każdą podsieć kontenera osobno — brak powodzi ARP.",
    "cni_desc": "Wtyczki CNI Kubernetes zarządzają siecią podów. Główne różnice w porównaniu do sieci Docker: IP na pod, polityki sieciowe, domyślnie brak NAT.",
    "cni_model": "Płaszczyzna danych",
    "cni_policy": "Polityka sieciowa",
    "cni_perf": "Wydajność",
    "cni_enc": "Szyfrowanie",
    "cni_usecase": "Najlepsze dla",
    "cni_vs_docker": "Sieci Docker mają zasięg hosta (bridge) lub swarma (overlay). Wtyczki K8s CNI zapewniają płaską sieć podów w całym klastrze, gdzie każdy pod otrzymuje ruterowalny adres IP bez NAT.",
    "desc_bridge": "Mostek programowy na hoście Docker — tryb domyślny. Kontenery współdzielą podsieć, NAT do świata zewnętrznego. Najlepsze dla aplikacji na jednym hoście.",
    "desc_overlay": "Overlay na wielu hostach z enkapsulacją VXLAN — wymaga Docker Swarm. Kontenery na różnych hostach pojawiają się w tym samym segmencie L2.",
    "desc_macvlan": "Każdy kontener otrzymuje własny MAC i IP bezpośrednio w segmencie L2 interfejsu nadrzędnego. Zero NAT, brak mostka. Idealne dla starszych aplikacji wymagających bezpośredniego dostępu do L2.",
    "desc_ipvlan": "Podobne do MACVLAN, ale wszystkie kontenery współdzielą MAC interfejsu nadrzędnego. Tryb L3 rutuje IP kontenerów — eliminuje ryzyko burz ARP w dużych wdrożeniach.",
    "desc_host": "Kontener współdzieli bezpośrednio przestrzeń nazw sieci hosta — brak izolacji, maksymalna wydajność. Stosuj dla obciążeń wrażliwych na opóźnienia, jak agenty monitorujące.",
    "desc_none": "Brak interfejsów sieciowych poza loopback. Pełna izolacja sieciowa. Stosuj, gdy kontener nie potrzebuje dostępu do sieci.",
