    "proto_scp_notes": "Protokół Secure Copy. Wysokie obciążenie CPU na starszych urządzeniach sieciowych ze względu na szyfrowanie SSH.",
    "proto_sftp_notes": "Protokół przesyłania plików SSH. Standardowy bezpieczny transport. Nieco wolniejszy niż SCP ze względu na narzut protokołu.",
    "proto_tftp_notes": "Trivial FTP. Blokowe transfery w trybie lockstep. Silnie ograniczony przez opóźnienia. Standardowy rozmiar bloku ogranicza go do ok. 1,5 - 3,5 Mbps.",
    "proto_ftp_notes": "Protokół przesyłania plików. Bardzo mały narzut, szybki, ale nieszyfrowany. Dane uwierzytelniające przesyłane w postaci jawnej.",
    "proto_http_notes": "Protokół przesyłania hipertekstu. Szybki, mały narzut. Doskonały dla lokalnych serwerów stagingowych.",
    "proto_https_notes": "Bezpieczny HTTP. Standard dla nowoczesnych pobrań ZTP / z chmury. Umiarkowany narzut kryptograficzny.",
    "plat_iosxe": "Cisco IOS / IOS-XE",
    "plat_iosxr": "Cisco IOS-XR",
    "plat_nxos": "Cisco NX-OS",
    "plat_junos": "Juniper Junos",
    "plat_eos": "Arista EOS",
    "plat_fortios": "Fortinet FortiOS",
    "plat_panos": "Palo Alto PAN-OS",
    "plat_linux": "Linux (curl / wget / scp)",
    "plat_f5": "F5 BIG-IP",
    "plat_huawei": "Huawei VRP",
    "plat_iosxe_notes": "Za pomocą \"show flash:\" upewnij się, że system plików flash ma wystarczającą ilość wolnego miejsca. W przypadku korzystania z SCP na serwerze musi być skonfigurowane \"ip scp server enable\", albo urządzenie musi mieć włączony routing SSH.",
    "plat_iosxr_notes": "Systemy plików IOS-XR używają disk0: lub disk1: zamiast flash:. Polecenia SCP/SFTP w XR interaktywnie pytają o hasło użytkownika. Kontekst routingu (VRF) można skonfigurować globalnie.",
    "plat_nxos_notes": "NX-OS domyślnie używa bootflash:. Sprawdź miejsce w systemie plików poleceniem \"dir bootflash:\". VRF musi mieć osiągalność IP do serwera; sprawdź routing domyślny lub VRF zarządzania.",
    "plat_junos_notes": "Kopie plików w Junos są umieszczane w /var/tmp/ lub /var/db/config/. Użyj \"show system storage\", aby sprawdzić miejsce na dysku. Transfery TFTP mogą wymagać konfiguracji protokołów routingu Junos lub użycia słowa kluczowego routing-instance.",
    "plat_eos_notes": "Urządzenia Arista używają flash:. Zweryfikuj poleceniem \"dir flash:\". Dla wysokiej przepustowości Arista obsługuje natywne, wysoce zoptymalizowane kopie HTTP/HTTPS.",
    "plat_fortios_notes": "Przywracanie TFTP w FortiOS zastępuje obraz rozruchowy i automatycznie restartuje urządzenie. Używaj ostrożnie. Zawsze wcześniej zapisz pliki konfiguracyjne.",
    "plat_panos_notes": "Palo Alto PAN-OS wymaga jawnych uprawnień administratora CLI do uruchamiania poleceń importu oprogramowania. Oprogramowanie można również pobrać bezpośrednio z oficjalnych aktualizacji wsparcia Palo Alto.",
    "plat_linux_notes": "Sprawdź uprawnienia do odczytu/zapisu katalogu docelowego. Upewnij się, że klient (scp, curl) jest zainstalowany. Transfery HTTP/HTTPS przez curl/wget można łatwo zrównoleglić.",
    "plat_f5_notes": "Sprawdź procesy bigstart i uprawnienia tras administracyjnych F5. Folder docelowy /shared/images/ to domyślna lokalizacja plików ISO F5.",
    "cmd_iosxe": "! Polecenie Cisco IOS/IOS-XE",
