    "explanation_title": "Zrozumienie NAT vs. PAT",
    "explanation_intro": "Network Address Translation (NAT) i Port Address Translation (PAT) to techniki mapowania jednej przestrzeni adresowej IP na inną, używane głównie do zachowania ograniczonych publicznych adresów IPv4 lub rozwiązywania konfliktów podsieci.",
    "nat_expl_title": "1. Co to jest NAT?",
    "nat_expl_desc": "NAT tłumaczy adresy IP w relacji 1-do-1. Może być Statyczny (stałe mapowanie jednego prywatnego IP na jeden publiczny IP, idealne dla serwerów publicznych) lub Dynamiczny (przydziela publiczny IP z puli do prywatnego hosta na żądanie. Po przydzieleniu wszystkich publicznych IP, kolejne hosty są blokowane do czasu zwolnienia adresu). Numery portów nie są modyfikowane.",
    "pat_expl_title": "2. Co to jest PAT (NAT Overload)?",
    "pat_expl_desc": "PAT (lub Port Address Translation / NAT Overload) tłumaczy zarówno adres IP, jak i numer portu źródłowego w relacji wiele-do-jednego (N-do-1). Wiele hostów prywatnych współdzieli jeden publiczny adres IP poprzez przypisanie unikalnych portów źródłowych (np. 192.168.1.10:5000 i 192.168.1.11:5000 mapują się na 203.0.113.10:1024 i 203.0.113.10:1025). Jest to standardowa metoda dla domowych routerów i dostępu do Internetu w firmach.",
    "comparison_table_title": "Podsumowanie Porównania",
