    "sec_prac_title": "Praktyki i ocena bezpieczeństwa sieci bezprzewodowej",
    "sec_prac_subtitle": "Przeprowadź audyt konfiguracji sieci bezprzewodowej względem standardowych w branży poziomów bezpieczeństwa.",
