    "about_body": "iperf to narzędzie do aktywnego pomiaru maksymalnej osiągalnej przepustowości w sieciach IP. Jeden host działa jako serwer (nasłuchujący), a drugi łączy się jako klient, aby przesyłać (lub odbierać) ruch przez TCP, UDP lub SCTP, raportując przepustowość, jitter i utratę pakietów. iperf3 (binarka iperf3) to nowoczesna wersja z wyjściem JSON oraz trybami reverse/bidirectional; iperf2 (binarka iperf) jest wielokliencki i lepszy do testów Wi-Fi oraz multicast. Obie wersje NIE są ze sobą kompatybilne — oba końce muszą korzystać z tej samej wersji.",
